mapper.update:
UPDATE file_object
SET created_at = NOW(3)
WHERE id = #{id}

mapper.select:
SELECT id, bucket, object_key, original_name, content_type,
       size_bytes, etag, kind, uploader_id, status, deleted_at, created_at
FROM file_object
WHERE uploader_id = #{uploaderId}
  AND kind = #{kind}
  AND size_bytes = #{sizeBytes}
  AND etag = #{etag}
  AND status IN (0, 1)
ORDER BY status DESC, id ASC
LIMIT 1

SELECT f.id, f.bucket, f.object_key, f.original_name, f.content_type,
       f.size_bytes, f.etag, f.kind, f.uploader_id, f.status, f.deleted_at, f.created_at
FROM file_object f
WHERE f.kind = #{kind}
  AND (
    (f.status = 0 AND f.deleted_at IS NOT NULL AND f.deleted_at < #{cutoff}
        AND NOT EXISTS (
            SELECT 1 FROM order_item oi WHERE oi.digital_file_id = f.id
        ))
    OR (f.status = 1 AND f.created_at < #{cutoff}
        AND NOT EXISTS (
            SELECT 1 FROM product p
            WHERE p.cover_file_id = f.id OR p.digital_file_id = f.id
        )
        AND NOT EXISTS (
            SELECT 1 FROM order_item oi WHERE oi.digital_file_id = f.id
        ))
  )
ORDER BY f.id
LIMIT #{limit}
